"""Self-contained replay of actual recorded simulation results."""
import json
from pathlib import Path


def write_report(path,data):
    template='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>四目避障动态仿真与实测耗时</title><style>
:root{color-scheme:light}*{box-sizing:border-box}body{margin:0;background:#f4f5f2;color:#202823;font:15px/1.65 system-ui,"Microsoft YaHei",sans-serif}main{max-width:1260px;margin:auto;padding:28px}h1{font-size:25px;margin-bottom:5px}h2{font-size:19px}small,.muted{color:#5f6861}.notice{padding:12px 16px;background:#e7ece6;margin:18px 0}.controls{display:flex;flex-wrap:wrap;gap:12px;align-items:center;margin:20px 0}select,button{padding:7px;font:inherit}input[type=range]{flex:1;min-width:160px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:24px}.pane{background:#fff;padding:18px}canvas{width:100%;display:block}img{width:100%;display:block}.stats{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.stat{border-top:2px solid #9ca99d;padding:8px 0}.value{font-size:24px;font-weight:600}.bench{width:100%;border-collapse:collapse}.bench th,.bench td{text-align:left;padding:8px 5px;border-bottom:1px solid #dce1dc}.bad{color:#9b3930}section{margin:25px 0}summary{cursor:pointer}a{color:#246e4d}@media(max-width:800px){.grid{grid-template-columns:1fr}.stats{grid-template-columns:1fr 1fr}}
</style><main><h1>四目避障：动态图像仿真与 CPU 实测</h1><p class="muted">i7-12700K · CPU OpenCV · GPU 未参与 · 2026-11-03</p><p class="notice">四路鱼眼画面由几何场景渲染，深度来自当前实际算法。这里的播放是已计算结果回放；点质量制动仅使用简化模型，尚未运行 PX4／ArduPilot SITL，也不代表 RK3588 或真实飞机性能。</p>
<section><h2>完整分辨率的计算耗时</h2><p>四路输入 1280×800；每组虚拟图 384×192，保持同样的匹配及质量筛选。每个线程配置连续测量 <span id="iterations"></span> 次。下表为处理加报文编码耗时，不含曝光、相机传输、飞控及物理制动。</p><table class="bench"><thead><tr><th>相机对并行 / OpenCV 线程</th><th>中位（ms）</th><th>P95（ms）</th><th>P99（ms）</th><th>平均计算率（Hz）</th><th>超 50 ms 比例</th></tr></thead><tbody id="benchmark"></tbody></table><p class="muted">20 Hz 新测距要求每组预算低于 50 ms，且还需给采集、排队和通信留余量。静态合成图的微基准不能保证复杂场景的最坏耗时。</p></section>
<section><h2>动态仿真回放</h2><div class="controls"><select id="scenario"></select><button id="play">播放</button><input id="timeline" type="range" min="0" value="0" step="1"><span id="frame-label"></span><select id="playback"><option value="1">1×模型时间</option><option value="0.5">0.5×</option><option value="2">2×</option></select></div><p id="scenario-description"></p><div class="stats"><div class="stat">本帧算法耗时<div class="value" id="compute"></div></div><div class="stat">前向保守测距<div class="value" id="distance"></div></div><div class="stat">有效方向 / 72<div class="value" id="coverage"></div></div></div><div class="grid"><div class="pane"><h2>俯视场景与距离输出</h2><canvas id="map" width="700" height="600"></canvas><small>横轴：世界 x（米），纵轴：世界 y（米）。方块为障碍，三角为机体；绿线为算法距离，未显示方向为未知。俯视图没有表达 z 高度。</small></div><div><div class="pane"><h2>实际送入算法的四目图像</h2><img id="cameras" alt="四路合成鱼眼输入"><small>上排：前、右；下排：后、左。动态仿真为 640×400 输入，不与上面的 1280×800 耗时混淆。</small></div><p id="state"></p><p id="case-result"></p></div></div><section><h2>本场景处理耗时随帧变化</h2><canvas id="chart" width="1100" height="200"></canvas><small>横轴：帧序号；纵轴：CPU 处理耗时（ms）。绿色为实际耗时；红虚线为 20 Hz 对应的 50 ms 预算。渲染耗时另计。</small></section></section>
<details><summary>试验边界与复现</summary><p>场景包括：向箱体接近、偏航旋转、前相机黑帧、低纹理表面，以及 1 m/s、3 m/s 的简化制动。简化制动假设：测距周期 0.1 s、采集到控制延迟 0.15 s、减速度 1 m/s²、余量 1 m；这些是模型输入，并非对真实飞机的测量。</p><p>简化控制器根据前向五个分区的有效值决定是否制动；没有模拟姿态、桨盘、风和电机。未知时制动是本演示策略，不能认为 PX4/AP 已采用相同行为。</p><p>运行工具：<code>python tools/benchmark_realtime.py --output data/benchmark.json</code>；<code>python tools/simulate_motion.py --output data/motion --benchmark data/benchmark.json</code>。输出 simulation.json 保存完整帧结果，网页无需联网。</p></details></main><script>
const D=__DATA__,names={approach:'接近前方箱体',yaw:'原地偏航扫描',texture_and_dropout:'黑帧与低纹理',point_mass_1mps:'简化闭环：初速 1 m/s',point_mass_3mps:'简化闭环：初速 3 m/s'};let current=0,index=0,playing=false,last=0,clock=0;const $=s=>document.querySelector(s);const fmt=(v,n=1)=>Number(v).toFixed(n);D.cases.forEach((c,i)=>{let o=document.createElement('option');o.value=i;o.textContent=names[c.name]||c.name;$('#scenario').appendChild(o)});
if(D.benchmark){$('#iterations').textContent=D.benchmark.profiles[0].iterations;D.benchmark.profiles.forEach(p=>{const tr=document.createElement('tr');[p.pair_workers+' / '+p.opencv_threads,fmt(p.median_ms),fmt(p.p95_ms),fmt(p.p99_ms),fmt(p.mean_compute_rate_hz),fmt(p.over_50ms_percent)+'%'].forEach(v=>{let td=document.createElement('td');td.textContent=v;tr.appendChild(td)});$('#benchmark').appendChild(tr)})}
const map=$('#map'),ctx=map.getContext('2d');function xy(x,y){return [80+(x+3.5)*82,60+(y+2.8)*82]}function line(a,b,color,width=1){ctx.strokeStyle=color;ctx.lineWidth=width;ctx.beginPath();ctx.moveTo(...a);ctx.lineTo(...b);ctx.stroke()}function drawMap(f){ctx.clearRect(0,0,700,600);ctx.fillStyle='#fff';ctx.fillRect(0,0,700,600);ctx.font='14px sans-serif';ctx.fillStyle='#5f6861';for(let x=-3;x<=3;x++){line(xy(x,-2.8),xy(x,2.5),'#e6ebe6');ctx.fillText(x+' m',xy(x,2.5)[0]-10,525)}for(let y=-2;y<=2;y++){line(xy(-3.5,y),xy(3,y),'#e6ebe6');ctx.fillText(y+' m',30,xy(-3.5,y)[1]+5)}ctx.strokeStyle='#657266';ctx.lineWidth=2;ctx.strokeRect(...xy(-3.5,-2.8),6.5*82,5.3*82);ctx.fillStyle='#c8cdc6';ctx.fillRect(...xy(1.4,-.35),.4*82,.7*82);let c=D.cases[current];ctx.strokeStyle='#b4beb4';ctx.lineWidth=2;ctx.beginPath();c.frames.slice(0,index+1).forEach((r,i)=>{let p=xy(r.x_m,0);i?ctx.lineTo(...p):ctx.moveTo(...p)});ctx.stroke();let p=xy(f.x_m,0),yaw=f.yaw_deg*Math.PI/180;f.distances_cm.forEach((d,i)=>{if(d===65535)return;let a=yaw+i*5*Math.PI/180;line(p,xy(f.x_m+Math.cos(a)*d/100,Math.sin(a)*d/100),'#3b8968',1)});ctx.save();ctx.translate(...p);ctx.rotate(yaw);ctx.beginPath();ctx.moveTo(13,0);ctx.lineTo(-9,-8);ctx.lineTo(-9,8);ctx.closePath();ctx.fillStyle='#1d3227';ctx.fill();ctx.restore();ctx.fillStyle='#202823';ctx.fillText('世界 x（米） →',280,570);ctx.save();ctx.translate(15,320);ctx.rotate(-Math.PI/2);ctx.fillText('世界 y（米）',0,0);ctx.restore();ctx.fillText('箱体',xy(1.4,-.35)[0]-4,xy(1.4,-.35)[1]-10)}
function drawChart(){const canvas=$('#chart'),g=canvas.getContext('2d'),rows=D.cases[current].frames;g.clearRect(0,0,1100,200);g.fillStyle='#fff';g.fillRect(0,0,1100,200);let max=Math.max(70,...rows.map(r=>r.processing_ms))*1.15;const x=i=>60+i*1000/Math.max(1,rows.length-1),y=v=>160-v/max*130;g.font='12px sans-serif';g.fillStyle='#5f6861';for(let v=0;v<max;v+=20){g.strokeStyle='#e1e6e0';g.beginPath();g.moveTo(60,y(v));g.lineTo(1060,y(v));g.stroke();g.fillText(v+' ms',5,y(v)+4)}g.setLineDash([6,4]);g.strokeStyle='#a0483c';g.beginPath();g.moveTo(60,y(50));g.lineTo(1060,y(50));g.stroke();g.setLineDash([]);g.strokeStyle='#28744e';g.lineWidth=2;g.beginPath();rows.forEach((r,i)=>i?g.lineTo(x(i),y(r.processing_ms)):g.moveTo(x(i),y(r.processing_ms)));g.stroke();g.strokeStyle='#26372b';g.beginPath();g.moveTo(x(index),20);g.lineTo(x(index),165);g.stroke();g.fillStyle='#26372b';g.fillText('帧序号 0',60,190);g.fillText(rows.length-1,1030,190)}
function show(){const c=D.cases[current],f=c.frames[index];$('#timeline').max=c.frames.length-1;$('#timeline').value=index;$('#frame-label').textContent=`${index+1}/${c.frames.length} · 模型 t=${fmt(f.t_s,2)} s`;$('#compute').textContent=fmt(f.processing_ms)+' ms';$('#distance').textContent=f.front_clearance_m===null?'未知':fmt(f.front_clearance_m,2)+' m';$('#coverage').textContent=f.valid_sectors+' / 72';$('#cameras').src=f.thumbnail;$('#state').textContent=`世界 x=${fmt(f.x_m,2)} m，偏航 ${fmt(f.yaw_deg)}°；速度 ${fmt(f.speed_mps,2)} m/s；状态 ${f.fault||f.controller_state}。本帧渲染 ${fmt(f.render_ms)} ms，未计入算法耗时。`;$('#scenario-description').textContent=c.kind.includes('point mass')?'简化点质量控制闭环：算法输出参与制动计算，飞控本体未运行。':'按预设位姿生成图像，检查真实算法输出随距离、朝向或图像故障变化。';$('#case-result').textContent=c.summary.final_true_box_clearance_m!==undefined?`模型结果：${c.summary.collision?'与箱体接触':'未与箱体接触'}；最终速度 ${fmt(c.summary.final_speed_mps,2)} m/s；机体中心到箱体前表面 x 向间距 ${fmt(c.summary.final_true_box_clearance_m,2)} m。`:`本场景 CPU 处理 P95=${fmt(c.summary.processing_p95_ms)} ms；前向未知 ${c.summary.front_unknown_frames}/${c.summary.frames} 帧。`;drawMap(f);drawChart()}
$('#scenario').onchange=e=>{current=+e.target.value;index=0;clock=0;show()};$('#timeline').oninput=e=>{index=+e.target.value;clock=0;show()};$('#play').onclick=()=>{playing=!playing;if(index===D.cases[current].frames.length-1)index=0;$('#play').textContent=playing?'暂停':'播放';clock=0;show()};function tick(t){if(playing){clock+=(t-last)/1000*+$('#playback').value;if(clock>=.1){index++;clock=0;if(index>=D.cases[current].frames.length){index=D.cases[current].frames.length-1;playing=false;$('#play').textContent='播放'}show()}}last=t;requestAnimationFrame(tick)}show();requestAnimationFrame(tick);
</script></html>'''
    approach=next((c for c in data['cases'] if c['name']=='approach'),None)
    if approach:
        bad=[r for r in approach['frames'] if r['front_clearance_m'] is not None and r['front_clearance_m']<r['true_front_box_clearance_m']/2]
        note=f"本次接近场景有 {len(bad)}/{len(approach['frames'])} 帧输出低于几何真值的一半。"
        if bad:
            note+=f"例如真值 {bad[0]['true_front_box_clearance_m']:.2f} m 时输出 {bad[0]['front_clearance_m']:.2f} m。"
        note+='算法算得快不代表测距已经可靠；保守下界与几何真值的偏差还需分析。对照下方真值与输出，不能把制动演示当作实飞验收。'
        template=template.replace('<p id="scenario-description"></p>',
            '<p id="scenario-description"></p><p class="notice">'+note+'</p>')
    template=template.replace('i7-12700K · CPU OpenCV · GPU 未参与 · 2026-11-03','CPU OpenCV · GPU 未参与 · 实际算法输出回放')
    template=template.replace('动态仿真为 640×400 输入',f"动态仿真为 {data['sensor_size'][0]}×{data['sensor_size'][1]} 输入")
    template=template.replace('<section><h2>本场景处理耗时随帧变化</h2>',
        '<section id="distance-section"><h2>前向距离：真值与实际输出</h2><canvas id="distance-chart" width="1100" height="220"></canvas><small>横轴：帧序号；纵轴：距离（米）。灰色：几何箱体前表面间距；绿色：前向五个分区的保守距离；橙色：第 0 分区距离。断线表示未知，仅在接近箱体场景比较。</small></section><section><h2>本场景处理耗时随帧变化</h2>')
    template=template.replace('function show(){', '''function drawDistance(){const c=D.cases[current],section=$('#distance-section');section.style.display=c.name==='approach'?'block':'none';if(c.name!=='approach')return;const canvas=$('#distance-chart'),g=canvas.getContext('2d'),rows=c.frames;g.clearRect(0,0,1100,220);g.fillStyle='#fff';g.fillRect(0,0,1100,220);g.font='12px sans-serif';g.fillStyle='#5f6861';const x=i=>60+i*1000/(rows.length-1),y=v=>170-v/3.5*140;for(let v=0;v<=3;v++){g.strokeStyle='#e1e6e0';g.beginPath();g.moveTo(60,y(v));g.lineTo(1060,y(v));g.stroke();g.fillText(v+' m',10,y(v)+4)}for(const [key,color]of [['truth','#69736b'],['front','#28744e'],['centre','#b56b2b']]){g.strokeStyle=color;g.lineWidth=2;let started=false;g.beginPath();rows.forEach((r,i)=>{let v=key==='truth'?r.true_front_box_clearance_m:key==='front'?r.front_clearance_m:r.distances_cm[0]===65535?null:r.distances_cm[0]/100;if(v===null){started=false;return}if(started)g.lineTo(x(i),y(v));else g.moveTo(x(i),y(v));started=true});g.stroke()}g.strokeStyle='#26372b';g.beginPath();g.moveTo(x(index),15);g.lineTo(x(index),175);g.stroke();g.fillText('帧序号 0',60,205);g.fillText(rows.length-1,1030,205)}
function show(){''')
    template=template.replace('drawMap(f);drawChart()', 'drawMap(f);drawChart();drawDistance()')
    template=template.replace('世界 x=${fmt(f.x_m,2)} m，偏航', '箱体前表面 x 向真实间距=${fmt(f.true_front_box_clearance_m,2)} m；世界 x=${fmt(f.x_m,2)} m，偏航')
    if data.get('sustained'):
        s=data['sustained']
        if 'profiles' in s:
            s=s['profiles'][0]
        detail=(f"<p class=\"notice\">最佳线程组合另连续计算 {s['iterations']} 次：中位 {s['median_ms']:.1f} ms，"
                f"P95 {s['p95_ms']:.1f} ms，P99 {s['p99_ms']:.1f} ms，最大 {s['max_ms']:.1f} ms；"
                f"超过 50 ms 的比例 {s['over_50ms_percent']:.1f}%。这些仅是当时电脑负载下的固定图像计算观测。</p>")
        template=template.replace('<section><h2>动态仿真回放</h2>',detail+'<section><h2>动态仿真回放</h2>')
    Path(path).write_text(template.replace('__DATA__',json.dumps(data,ensure_ascii=False).replace('</','<\\/')),encoding='utf-8')
